import {useEffect,useState,useRef} from 'react';
import {LayoutDashboard,FolderSearch,Sparkles,ChartNoAxesCombined,GitBranch,ShieldCheck,Plug,ArrowUpRight,ArrowRight,Check,ChevronDown,ChevronRight,Plus,Upload,Download,RefreshCw,Box,MapPin,Activity,TriangleAlert,Leaf,Clock,ShoppingBasket,CheckCircle2,X,LoaderCircle,SlidersHorizontal,FlaskConical,LockKeyhole,FileText,Search,Wallet,Target,Menu} from 'lucide-react';
import {ResponsiveContainer,BarChart,Bar,XAxis,YAxis,Tooltip,CartesianGrid,AreaChart,Area} from 'recharts';
import {api,post,setCsrf,money,number,timestamp,Dict,ApiError} from './api';
